'use strict';
// The export object is an accessor whose getter answers 0 on the first read and an object after it.
let reads = 0;

function current() {
	reads += 1;
	console.log('first-zero: read', reads);
	return reads === 1 ? 0 : {reads};
}

Object.defineProperty(module, 'exports', {enumerable: true, get: current});
